import React, { useState, useEffect, useCallback } from "react";
import api from "../../services/api";
import { API_ENDPOINTS } from "../../services/apiEndpoints";
import TweetCard from "../tweetCard";
import { DragDropContext, Droppable, Draggable } from "react-beautiful-dnd";

const TweetList = ({ wallId }) => {
    const [tweets, setTweets] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    // Fetch tweets when component mounts or wallId changes
    useEffect(() => {
        const fetchTweets = async () => {
            try {
                if (!wallId) throw new Error("Wall ID is required to fetch tweets");
                const response = await api.get(API_ENDPOINTS.GET_TWEETS_BY_WALL(wallId));
                setTweets(response.data || []);
                setLoading(false);
            } catch (err) {
                console.error("Fetch Tweets Error:", err.message);
                setError(err.response?.data?.message || "Failed to load tweets");
                setLoading(false);
            }
        };

        fetchTweets();
    }, [wallId]);

    // Handle tweet randomization
    const handleRandomize = async () => {
        try {
            setError(null);
            if (tweets.length === 0) {
                setError("No tweets to randomize");
                return;
            }
            const response = await api.patch(API_ENDPOINTS.REORDER_TWEETS(wallId));
            setTweets(response.data || []);
        } catch (err) {
            console.error("Randomize Tweets Error:", err.message);
            setError(err.response?.data?.message || "Failed to randomize tweets");
        }
    };

    // Handle drag & drop reorder
    const onDragEnd = (result) => {
        const { source, destination } = result;
        if (!destination) return; // Dropped outside the list

        // Reorder tweets array
        const newTweets = Array.from(tweets);
        const [movedTweet] = newTweets.splice(source.index, 1);
        newTweets.splice(destination.index, 0, movedTweet);

        setTweets(newTweets);
    };

    // Save reordered tweets to the backend
    const handleSaveOrder = async () => {
        try {
            await api.put(API_ENDPOINTS.UPDATE_TWEET_ORDER(wallId), { tweets });
            console.log("Tweet order saved:", tweets);
        } catch (err) {
            setError("Failed to save tweet order");
            console.error("Error saving tweet order:", err);
        }
    };

    // Handle tweet deletion
    const handleDelete = useCallback(async (tweetId) => {
        if (!window.confirm("Are you sure you want to delete this tweet?")) return;

        try {
            setError(null);
            await api.delete(API_ENDPOINTS.DELETE_TWEET(wallId, tweetId));
            setTweets((prevTweets) => prevTweets.filter((tweet) => tweet.id !== tweetId));
        } catch (err) {
            console.error("Delete Tweet Error:", err.message);
            setError(err.response?.data?.message || "Failed to delete tweet");
        }
    }, [wallId]);

    if (loading) return <div className="text-center p-6 text-gray-500">Loading tweets...</div>;
    if (error) return <div className="text-center p-6 text-red-500">{error}</div>;

    return (
        <div className="p-6">
            {/* Action Buttons */}
            <div className="flex justify-between mb-4">
                <button
                    onClick={handleRandomize}
                    className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600 transition disabled:bg-gray-400 disabled:cursor-not-allowed"
                    disabled={tweets.length === 0 || loading}
                >
                    Randomize Tweets
                </button>
                <button
                    onClick={handleSaveOrder}
                    className="bg-green-500 text-white px-4 py-2 rounded hover:bg-green-600 transition disabled:bg-gray-400 disabled:cursor-not-allowed"
                    disabled={tweets.length === 0}
                >
                    Save Order
                </button>
            </div>

            {/* Drag & Drop Context */}
            <DragDropContext onDragEnd={onDragEnd}>
                <Droppable droppableId="tweets-list">
                    {(provided) => (
                        <div
                            className="flex flex-wrap gap-6"
                            ref={provided.innerRef}
                            {...provided.droppableProps}
                        >
                            {tweets.map((tweet, index) => (
                                <Draggable key={tweet.id} draggableId={tweet.id.toString()} index={index}>
                                    {(provided) => (
                                        <div
                                            ref={provided.innerRef}
                                            {...provided.draggableProps}
                                            {...provided.dragHandleProps}
                                            className="w-full sm:w-1/2 lg:w-1/3"
                                        >
                                            <TweetCard tweet={tweet} onDelete={handleDelete} />
                                        </div>
                                    )}
                                </Draggable>
                            ))}
                            {provided.placeholder}
                        </div>
                    )}
                </Droppable>
            </DragDropContext>
        </div>
    );
};

export default TweetList;
